package com.af9.core.startup.layout;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * The Orbital Array Mk2's layout (no GregTech in here), generated by tools/orbital_mk2_layout.py from Janne's orbital.nbt
 * into {@code layouts/orbital_mk2.txt}: do not edit it by hand, change the file (or the tool) and generate again. 73
 * aisles (the controller's up, west), each 99 rows (the controller's front, up: the first row is the foot, the last the
 * controller's), each 73 characters (its right, south). In the file the aisles follow one another with a line
 * {@code ---} between them, a row to a line.
 *
 * <pre>
 *   . anything         # air that stays air (the wafer)      K the controller
 *   L af9:orbital_combined_structure_casing   D af9:orbital_truss_casing   E af9:orbital_girder_casing
 *   M af9:orbital_magnet_casing   N af9:orbital_light_casing   H gtceu:atomic_casing   C gtceu:nonconducting_casing
 *   F gtceu:tungsten_carbide_frame   S gtceu:superconducting_coil   G gtceu:fusion_glass   V gtceu:heat_vent
 *   T gtceu:tungstensteel_turbine_casing   P gtceu:computer_casing   g create:metal_girder
 *   n gtceu:magnetic_neodymium_block   s gtceu:magnetic_samarium_block   R a rotor holder, UV or better
 *   O nonconducting casing or a hatch (the chamber deck)   Y nonconducting casing or an orbital module
 * </pre>
 *
 * A {@code .} in the file is "anything": the pattern gets a space there.
 */
public final class OrbitalMk2Layout {

    private OrbitalMk2Layout() {}

    private static final String RESOURCE = "/layouts/orbital_mk2.txt";

    /** The slices as the pattern wants them: aisles of rows, {@code .} turned into a space. */
    public static String[][] slices() {
        List<String[]> aisles = new ArrayList<>();
        List<String> rows = new ArrayList<>();
        try (InputStream in = OrbitalMk2Layout.class.getResourceAsStream(RESOURCE)) {
            if (in == null) throw new IllegalStateException("missing resource " + RESOURCE);
            BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.equals("---")) {
                    aisles.add(rows.toArray(String[]::new));
                    rows.clear();
                } else if (!line.isEmpty()) {
                    rows.add(line.replace('.', ' '));
                }
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        if (!rows.isEmpty()) aisles.add(rows.toArray(String[]::new));
        return aisles.toArray(String[][]::new);
    }
}
